// SecureNet - FINAL STABLE (Run Once for All Items)
// - Normaliza payload Kuma
// - Detecta DOWN/UP
// - Mapea monitor_code -> container
// - Anti-duplicados por monitor+estado con TTL separado
// - NO dropea errores de mapeo (los marca como ERROR para notificar)

function nowIso() { return new Date().toISOString(); }

const staticData = $getWorkflowStaticData('node');
if (!staticData.seen) staticData.seen = {};

const nowSec = Math.floor(Date.now() / 1000);

// TTLs separados (recomendado)
const TTL_DOWN = 120; // evita spam de DOWN (más agresivo)
const TTL_UP   = 45;  // UP suele repetirse más, TTL menor
const CLEANUP_TTL = Math.max(TTL_DOWN, TTL_UP) * 6;

// cleanup cache
for (const [sig, t] of Object.entries(staticData.seen)) {
  if (nowSec - t > CLEANUP_TTL) delete staticData.seen[sig];
}

const MAP = {
  HOMEPAGE: "homepage",
  N8N: "n8n",
  PORTAINER: "portainer",
  KUMA: "uptime-kuma",
  // añade aquí más monitores si los creas:
  // WORDPRESS: "wordpress",
};

const out = [];

for (const item of $input.all()) {
  const incoming = item.json?.body ?? item.json ?? {};

  let msg = incoming.msg;
  let monitorCode = incoming.monitor_code;
  let statusField = incoming.status;

  // Caso raro: form-urlencoded (una sola clave que es JSON)
  if ((!msg || !monitorCode) && incoming && typeof incoming === "object") {
    const keys = Object.keys(incoming);
    if (keys.length === 1 && keys[0].trim().startsWith("{")) {
      try {
        const parsed = JSON.parse(keys[0]);
        msg = msg ?? parsed.msg;
        monitorCode = monitorCode ?? parsed.monitor_code;
        statusField = statusField ?? parsed.status;
      } catch (e) {}
    }
  }

  msg = (msg ?? "").toString().trim();
  monitorCode = (monitorCode ?? "").toString().trim();
  statusField = (statusField ?? "").toString().trim();

  const ts = nowIso();

  // Validación mínima (no “pierdas” eventos silenciosamente)
  if (!msg || !monitorCode) {
    out.push({
      json: {
        drop: false,
        status: "ERROR",
        reason: "Missing msg/monitor_code",
        ts,
        incoming
      }
    });
    continue;
  }

  const msgLower = msg.toLowerCase();
  const statusLower = statusField.toLowerCase();

  // Detectores robustos (prioriza statusField si viene)
  const isDown =
    statusLower === "down" ||
    msgLower.includes("[🔴 down]") ||
    /\[\s*🔴\s*down\s*\]/i.test(msg);

  const isUp =
    statusLower === "up" ||
    msgLower.includes("[✅ up]") ||
    msgLower.includes("[🟢 up]") ||
    /\[\s*(✅|🟢)\s*up\s*\]/i.test(msg);

  let status = "INFO";
  if (isDown) status = "DOWN";
  else if (isUp) status = "UP";

  // Extraer nombre del monitor del msg (primer [ ... ])
  let monitorName = "";
  const m = msg.match(/^\s*\[([^\]]+)\]/);
  if (m?.[1]) monitorName = m[1].trim();
  if (!monitorName) monitorName = monitorCode;

  const codeNormalized = monitorCode.toUpperCase();

  const container = MAP[codeNormalized] || "";

  // Si es DOWN y no hay mapping, NO dropear: marca ERROR para notificar
  if (status === "DOWN" && !container) {
    out.push({
      json: {
        drop: false,
        status: "ERROR",
        reason: `No container mapping for monitor_code=${codeNormalized}`,
        ts,
        msg,
        monitorName,
        monitorCode: codeNormalized,
        container: "",
        isDown,
        isUp
      }
    });
    continue;
  }

  // Dedupe estable: SOLO monitor+status
  // Así no depende de msg (que puede cambiar o repetirse)
  const signature = `${codeNormalized}|${status}`;

  let isDup = false;
  if (status === "DOWN" || status === "UP") {
    const ttl = status === "DOWN" ? TTL_DOWN : TTL_UP;
    const last = staticData.seen[signature];
    isDup = !!(last && (nowSec - last) < ttl);

    // Guarda siempre el último para bloquear spam
    staticData.seen[signature] = nowSec;
  }

  out.push({
    json: {
      drop: isDup,
      reason: isDup ? `Duplicate ${signature} within TTL` : "ok",
      ts,
      status,
      msg,
      monitorName,
      monitorCode: codeNormalized,
      container,
      isDown,
      isUp,
      signature
    }
  });
}

return out;

